'use strict';
window.PrepJourneyModel=(()=>{
  const levels={beginner:{name:'Starting fresh',stage:'foundations',description:'Build the basics before your first coding task.'},intermediate:{name:'Know the basics',stage:'guided',description:'Connect familiar concepts to practical problems.'},advanced:{name:'Ready to stretch',stage:'independent',description:'Start with independent work and revisit any gaps.'}};
  const domains=['Investment Banking','Core Banking','Ecommerce','AI','Cloud','Data Engineering'];
  const roles=['software-engineer','qa-sdet','test-director','engineering-manager','data-engineer','ai-ml-engineer','cloud-devops'];
  function profile(input={}){return {version:1,level:Object.hasOwn(levels,input.level)?input.level:'beginner',language:['java','python'].includes(input.language)?input.language:'java',domain:domains.includes(input.domain)?input.domain:'Investment Banking',role:roles.includes(input.role)?input.role:'software-engineer',minutes:[20,40,60].includes(Number(input.minutes))?Number(input.minutes):20};}
  const topic=(id,title,minutes=12)=>({id,title,kind:'concept',minutes,independent:!id.startsWith('1-')});
  const coding=(id,title,independent=false)=>({id,title,kind:'coding',minutes:25,independent});
  const rehearsal=(id,title,round)=>({id,title,kind:'rehearsal',minutes:10,round});
  function curriculum(input){
    const p=profile(input),sdet=['qa-sdet','test-director'].includes(p.role);
    const domainTopics={'Core Banking':[['core-ledger','Understand balances and reconciliation'],['core-idempotency','Make retries safe']],'Ecommerce':[['ecommerce-inventory','Reason about stock reservations'],['ecommerce-checkout','Handle checkout failures']],'AI':[['ai-evaluation','Evaluate an AI change'],['ai-rag','Check evidence and grounding']],'Cloud':[['cloud-reliability','Use deadlines and retry budgets'],['cloud-access','Understand least privilege']],'Data Engineering':[['data-replay','Replay events safely'],['data-quality','Check data contracts']]};
    return [
      {id:'foundations',name:'Build your foundations',short:'Foundations',label:'Understand',description:'Get comfortable with the ideas you will use in almost every technical interview.',outcomes:['Explain an object, a constructor and missing values.','Choose a collection from its ordering and duplicate rules.','Give a short, structured explanation in your own words.'],tasks:[topic('1-01-objects-constructors-and-immutability','Understand objects and starting state'),topic('1-02-equality-null-handling-and-object-utility-methods','Compare values and handle missing input'),topic('1-04-collections-lists-sets-queues-and-copies','Choose a collection'),topic('shared-structured-answers','Structure a clear answer')]},
      {id:'guided',name:'Practise with support',short:'Guided practice',label:'Apply',description:'Work through small examples, make a prediction and use a hint when you need one.',outcomes:['Read a method and predict what it returns.','Build a filter, transformation or running total.','Use a failing case to improve an implementation.'],tasks:[topic('1-05-maps-sorted-maps-and-comparators','Connect keys to values'),topic('1-03-bigdecimal-financial-arithmetic-and-rounding','Calculate decimal money correctly'),topic('1-06-streams-pipelines-filtering-mapping-and-ordering','Filter and transform records'),coding('2-01-find-duplicate-trade-ids-in-second-occurrence-order','Find duplicate IDs with a clear ordering rule')]},
      {id:'independent',name:'Solve on your own',short:'Independent coding',label:'Solve',description:'Clarify the contract, attempt the problem before opening hints and explain the trade-offs.',outcomes:['Solve a new prompt before seeing the worked answer.','Test normal cases, invalid input and boundaries.','Explain time, space and the limitations of your solution.'],tasks:p.language==='java'&&sdet?[coding('banking-debug-price-scale','Investigate a false price mismatch',true),coding('banking-test-missing-trades','Design tests that catch reconciliation defects',true),coding('banking-test-order-validation','Find faulty order validators',true)]:[coding('2-06-find-trades-missing-from-actual-results','Reconcile missing records',true),coding('2-03-validate-a-trading-order-and-return-all-errors','Report every validation error',true),coding('2-04-calculate-total-trade-quantity-by-symbol','Aggregate quantities safely',true)]},
      {id:'depth',name:'Develop technical depth',short:'Technical depth',label:'Reason',description:'Move beyond a working answer. Reason about concurrency, failure and the context of the role.',outcomes:['Explain which operations need coordination.','Describe failure, waiting and cleanup behaviour.','Connect a technical choice to domain constraints.'],tasks:[topic('1-07-collectors-grouping-and-financial-reductions','Group records and reduce totals'),topic('1-08-threads-executors-futures-and-lifecycle-management','Own task execution and cleanup'),topic('1-09-atomic-updates-concurrent-maps-and-bounded-queues','Protect a complete shared update'),topic('1-10-threadlocal-context-and-completablefuture-composition','Handle request context and async work'),...(domainTopics[p.domain]||[]).map(([id,title])=>topic(id,title)),...(p.language==='java'?[coding(sdet?'banking-project-regression-runner':p.domain==='Core Banking'?'banking-project-ledger':'banking-project-reconciler',sdet?'Build a bounded regression runner':p.domain==='Core Banking'?'Build an idempotent ledger component':'Build a complete reconciliation component',true),coding('banking-project-concurrent-events','Make concurrent event counting reliable',true)]:[coding('2-19-reconcile-two-complete-trade-snapshots','Reconcile complete trade snapshots',true)]),rehearsal('role-'+p.role+'-technical','Explain a decision for your target role','technical')]},
      {id:'mastery',name:'Practise the complete interview',short:'Interview rehearsal',label:'Communicate',description:'Bring your knowledge, reasoning and experience into a coherent conversation across all five rounds.',outcomes:['Tell a relevant, truthful story about your experience.','Explain a solution and respond to follow-up questions.','Discuss uncertainty and decisions with stakeholders.'],tasks:[rehearsal('intro-about-yourself','Introduce yourself with a relevant example','introduction'),rehearsal('shared-live-exercise','Talk through an unfamiliar coding problem','coding'),rehearsal('technical-failure','Reason about a partial failure','technical'),rehearsal('manager-release','Recommend a release decision','manager'),rehearsal('hr-development','Discuss a development area honestly','hr')]}
    ];
  }
  const reflectionKey=(p,t)=>JSON.stringify([p.language,p.domain,p.role,t.id]);
  function taskStatus(task,p,evidence={}){
    if(task.kind==='concept'){const key=task.independent||p.language==='java'?task.id:task.id+'::'+p.language;return {done:(evidence.reviewed||[]).includes(key),source:'review',label:(evidence.reviewed||[]).includes(key)?'Self-reviewed':'Not reviewed yet'};}
    if(task.kind==='coding'){
      const spec=p.language==='java'?(evidence.catalogue||[]).find(item=>item.id===task.id):null;
      if(spec){
        const passed=(evidence.attempts||[]).filter(a=>a.problem_id===task.id&&a.language==='java'&&String(a.problem_version)===String(spec.version)&&a.mode==='check'&&a.status==='completed'&&a.result?.total>0&&a.result.total===spec.testCount&&a.result.passed===a.result.total);
        const clean=a=>a.assistance&&a.assistance.hints===0&&a.assistance.answerViewed===false&&a.assistance.solutionLoaded===false&&a.assistance.externalHelp===false;
        const done=passed.some(a=>!task.independent||clean(a));
        return {done,source:'checks',label:done?(task.independent?'Checks passed · no assistance recorded':'Contract checks passed'):passed.length?'Try again without recorded assistance':'Contract check to complete'};
      }
    }
    const reflection=evidence.reflections?.[reflectionKey(p,task)],done=reflection?.reviewed===true&&reflection.note?.trim().length>=20;
    return {done:!!done,source:'reflection',label:done?(task.kind==='coding'?'Self-reviewed practice':'Rehearsal recorded'):(task.kind==='coding'?'Manual practice':'Rehearsal to try')};
  }
  function recommend(stages,p,evidence){const entry=stages.findIndex(stage=>stage.id===levels[p.level].stage),ordered=[...stages.slice(Math.max(0,entry)),...stages.slice(0,Math.max(0,entry))];for(const stage of ordered){const task=stage.tasks.find(t=>!taskStatus(t,p,evidence).done);if(task)return {stage,task};}return null;}
  function session(minutes){const learn=Math.round(minutes/4),practise=Math.round(minutes/2);return {learn,practise,reflect:minutes-learn-practise};}
  return {levels,domains,roles,profile,curriculum,reflectionKey,taskStatus,recommend,session};
})();
